refentry.refsect1:
  &reftitle.examples;

   Exemple avec Yaf_Response_Abstract::__construct


<?php
/* en général, il n'est pas nécessaire de construire une réponse manuellement :
 * le distributeur en crée une et la met à disposition */
$response = Yaf_Dispatcher::getInstance()->getResponse();

/* la construction directe est surtout utile dans les tests */
$response = new Yaf_Response_Http();
$response->setBody("Hello World");

echo $response;
?>


   &example.outputs.similar;


Hello World
